     1	package com.pousada.api;
     2	
     3	import com.pousada.database.ReservationDao;
     4	import com.pousada.database.RoomDao;
     5	import com.pousada.model.Reservation;
     6	import com.pousada.model.ReservationStatus;
     7	import com.pousada.model.Room;
     8	import com.pousada.util.Dates;
     9	import com.pousada.util.Money;
    10	import io.javalin.http.Context;
    11	
    12	import java.math.BigDecimal;
    13	import java.time.LocalDate;
    14	import java.time.YearMonth;
    15	import java.util.*;
    16	
    17	public class ReportHandler {
    18	    public static void occupancy(Context ctx) throws Exception {
    19	        try {
    20	            String dateStr = ctx.queryParam("date");
    21	            if (dateStr == null) {
    22	                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "date parameter required"));
    23	                return;
    24	            }
    25	
    26	            LocalDate date = Dates.parseIso(dateStr);
    27	            Map<Integer, Room> roomMap = RoomDao.findAllAsMap();
    28	
    29	            StringBuilder csv = new StringBuilder();
    30	            csv.append("room,type,reservation,check_in,check_out\n");
    31	
    32	            int occupiedCount = 0;
    33	            for (int roomNum : new int[]{101, 102, 201, 202, 301}) {
    34	                List<Reservation> reservations = ReservationDao.findByRoomAndNight(roomNum, date);
    35	                if (!reservations.isEmpty()) {
    36	                    for (Reservation r : reservations) {
    37	                        if (r.status != ReservationStatus.CANCELLED) {
    38	                            Room room = roomMap.get(roomNum);
    39	                            csv.append(roomNum).append(",")
    40	                                    .append(room.type).append(",")
    41	                                    .append(r.id).append(",")
    42	                                    .append(Dates.formatCsv(r.checkIn)).append(",")
    43	                                    .append(Dates.formatCsv(r.checkOut)).append("\n");
    44	                            occupiedCount++;
    45	                        }
    46	                    }
    47	                }
    48	            }
    49	
    50	            csv.append("total,").append(occupiedCount).append("/5\n");
    51	
    52	            ctx.contentType("text/csv; charset=utf-8").result(csv.toString());
    53	        } catch (Exception e) {
    54	            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
    55	        }
    56	    }
    57	
    58	    public static void revenue(Context ctx) throws Exception {
    59	        try {
    60	            String monthStr = ctx.queryParam("month");
    61	            if (monthStr == null) {
    62	                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "month parameter required"));
    63	                return;
    64	            }
    65	
    66	            YearMonth ym = YearMonth.parse(monthStr);
    67	            List<Reservation> reservations = ReservationDao.findByMonthAndNotCancelled(ym.getYear(), ym.getMonthValue());
    68	
    69	            StringBuilder csv = new StringBuilder();
    70	            csv.append("reservation,room,check_in,check_out,status,amount\n");
    71	
    72	            BigDecimal total = BigDecimal.ZERO;
    73	
    74	            for (Reservation r : reservations) {
    75	                if (r.status != ReservationStatus.CANCELLED) {
    76	                    BigDecimal amount = r.amountPaid;
    77	                    if (r.refund != null) {
    78	                        amount = amount.subtract(r.refund);
    79	                    }
    80	
    81	                    csv.append(r.id).append(",")
    82	                            .append(r.roomNumber).append(",")
    83	                            .append(Dates.formatCsv(r.checkIn)).append(",")
    84	                            .append(Dates.formatCsv(r.checkOut)).append(",")
    85	                            .append(r.status.name()).append(",")
    86	                            .append(String.format("%.2f", amount)).append("\n");
    87	
    88	                    total = total.add(amount);
    89	                } else {
    90	                    // Cancelled non-refundable reservations still count
    91	                    if (r.amountPaid.compareTo(BigDecimal.ZERO) > 0) {
    92	                        BigDecimal amount = r.amountPaid;
    93	                        if (r.refund != null) {
    94	                            amount = amount.subtract(r.refund);
    95	                        }
    96	
    97	                        csv.append(r.id).append(",")
    98	                                .append(r.roomNumber).append(",")
    99	                                .append(Dates.formatCsv(r.checkIn)).append(",")
   100	                                .append(Dates.formatCsv(r.checkOut)).append(",")
   101	                                .append(r.status.name()).append(",")
   102	                                .append(String.format("%.2f", amount)).append("\n");
   103	
   104	                        total = total.add(amount);
   105	                    }
   106	                }
   107	            }
   108	
   109	            csv.append("total,,,,").append(String.format("%.2f", total)).append("\n");
   110	
   111	            ctx.contentType("text/csv; charset=utf-8").result(csv.toString());
   112	        } catch (Exception e) {
   113	            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
   114	        }
   115	    }
   116	}
