     1	package com.pousada.api;
     2	
     3	import com.fasterxml.jackson.databind.ObjectMapper;
     4	import com.pousada.database.ReservationDao;
     5	import com.pousada.model.Reservation;
     6	import com.pousada.model.RatePlanType;
     7	import com.pousada.service.ReservationService;
     8	import com.pousada.service.ApiException;
     9	import com.pousada.util.Dates;
    10	import com.pousada.util.Money;
    11	import io.javalin.http.Context;
    12	
    13	import java.math.BigDecimal;
    14	import java.time.LocalDate;
    15	import java.util.Map;
    16	
    17	public class ReservationHandler {
    18	    private static final ObjectMapper mapper = new ObjectMapper();
    19	
    20	    public static void create(Context ctx) throws Exception {
    21	        try {
    22	            Map<String, Object> body = mapper.readValue(ctx.body(), Map.class);
    23	
    24	            // Validate required fields
    25	            String[] requiredFields = {"roomNumber", "guestName", "guestEmail", "guestCpf",
    26	                    "checkIn", "checkOut", "guests", "ratePlan"};
    27	            for (String field : requiredFields) {
    28	                if (!body.containsKey(field)) {
    29	                    sendError(ctx, "INVALID_REQUEST", "Missing required field: " + field, 400);
    30	                    return;
    31	                }
    32	            }
    33	
    34	            int roomNumber = ((Number) body.get("roomNumber")).intValue();
    35	            String guestName = (String) body.get("guestName");
    36	            String guestEmail = (String) body.get("guestEmail");
    37	            String guestCpf = (String) body.get("guestCpf");
    38	            LocalDate checkIn = Dates.parseIso((String) body.get("checkIn"));
    39	            LocalDate checkOut = Dates.parseIso((String) body.get("checkOut"));
    40	            int guests = ((Number) body.get("guests")).intValue();
    41	            RatePlanType ratePlan = RatePlanType.valueOf((String) body.get("ratePlan"));
    42	            String companyCode = (String) body.get("companyCode");
    43	
    44	            Reservation reservation = ReservationService.createReservation(
    45	                    roomNumber, guestName, guestEmail, guestCpf,
    46	                    checkIn, checkOut, guests, ratePlan, companyCode
    47	            );
    48	
    49	            ctx.status(201).json(reservationToDto(reservation));
    50	        } catch (IllegalArgumentException e) {
    51	            sendError(ctx, "INVALID_REQUEST", "Invalid rate plan or date format", 400);
    52	        } catch (ApiException e) {
    53	            sendError(ctx, e.code, e.getMessage(), e.statusCode);
    54	        } catch (Exception e) {
    55	            sendError(ctx, "INVALID_REQUEST", e.getMessage(), 400);
    56	        }
    57	    }
    58	
    59	    public static void get(Context ctx) throws Exception {
    60	        try {
    61	            int id = Integer.parseInt(ctx.pathParam("id"));
    62	            Reservation reservation = ReservationService.getReservation(id);
    63	            ctx.json(reservationToDto(reservation));
    64	        } catch (ApiException e) {
    65	            sendError(ctx, e.code, e.getMessage(), e.statusCode);
    66	        } catch (Exception e) {
    67	            sendError(ctx, "INVALID_REQUEST", e.getMessage(), 400);
    68	        }
    69	    }
    70	
    71	    public static void confirm(Context ctx) throws Exception {
    72	        try {
    73	            int id = Integer.parseInt(ctx.pathParam("id"));
    74	            Reservation reservation = ReservationService.getReservation(id);
    75	
    76	            Map<String, Object> body = mapper.readValue(ctx.body(), Map.class);
    77	            if (!body.containsKey("amountPaid")) {
    78	                sendError(ctx, "INVALID_REQUEST", "Missing amountPaid", 400);
    79	                return;
    80	            }
    81	
    82	            BigDecimal amountPaid = new BigDecimal(body.get("amountPaid").toString());
    83	            Reservation confirmed = ReservationService.confirmReservation(id, amountPaid);
    84	            ctx.json(reservationToDto(confirmed));
    85	        } catch (ApiException e) {
    86	            sendError(ctx, e.code, e.getMessage(), e.statusCode);
    87	        } catch (Exception e) {
    88	            sendError(ctx, "INVALID_REQUEST", e.getMessage(), 400);
    89	        }
    90	    }
    91	
    92	    public static void cancel(Context ctx) throws Exception {
    93	        try {
    94	            int id = Integer.parseInt(ctx.pathParam("id"));
    95	            Reservation cancelled = ReservationService.cancelReservation(id);
    96	            ctx.json(reservationToDto(cancelled));
    97	        } catch (ApiException e) {
    98	            sendError(ctx, e.code, e.getMessage(), e.statusCode);
    99	        } catch (Exception e) {
   100	            sendError(ctx, "INVALID_REQUEST", e.getMessage(), 400);
   101	        }
   102	    }
   103	
   104	    public static void checkIn(Context ctx) throws Exception {
   105	        try {
   106	            int id = Integer.parseInt(ctx.pathParam("id"));
   107	            Reservation checkedIn = ReservationService.checkInReservation(id);
   108	            ctx.json(reservationToDto(checkedIn));
   109	        } catch (ApiException e) {
   110	            sendError(ctx, e.code, e.getMessage(), e.statusCode);
   111	        } catch (Exception e) {
   112	            sendError(ctx, "INVALID_REQUEST", e.getMessage(), 400);
   113	        }
   114	    }
   115	
   116	    public static void checkOut(Context ctx) throws Exception {
   117	        try {
   118	            int id = Integer.parseInt(ctx.pathParam("id"));
   119	            Reservation checkedOut = ReservationService.checkOutReservation(id);
   120	            String receipt = ReservationService.generateReceipt(checkedOut);
   121	            ctx.json(receiptToDto(checkedOut, receipt));
   122	        } catch (ApiException e) {
   123	            sendError(ctx, e.code, e.getMessage(), e.statusCode);
   124	        } catch (Exception e) {
   125	            sendError(ctx, "INVALID_REQUEST", e.getMessage(), 400);
   126	        }
   127	    }
   128	
   129	    public static void document(Context ctx) throws Exception {
   130	        try {
   131	            int id = Integer.parseInt(ctx.pathParam("id"));
   132	            Reservation reservation = ReservationService.getReservation(id);
   133	
   134	            if (reservation.amountPaid.compareTo(BigDecimal.ZERO) == 0) {
   135	                sendError(ctx, "OPERATION_NOT_ALLOWED", "Only paid reservations have receipts", 409);
   136	                return;
   137	            }
   138	
   139	            String receipt = ReservationService.generateReceipt(reservation);
   140	            ctx.json(receiptToDto(reservation, receipt));
   141	        } catch (ApiException e) {
   142	            sendError(ctx, e.code, e.getMessage(), e.statusCode);
   143	        } catch (Exception e) {
   144	            sendError(ctx, "INVALID_REQUEST", e.getMessage(), 400);
   145	        }
   146	    }
   147	
   148	    private static Map<String, Object> reservationToDto(Reservation r) {
   149	        Map<String, Object> map = new java.util.LinkedHashMap<>();
   150	        map.put("id", r.id);
   151	        map.put("roomNumber", r.roomNumber);
   152	        map.put("guestName", r.guestName);
   153	        map.put("guestEmail", r.guestEmail);
   154	        map.put("guestCpf", r.guestCpf);
   155	        map.put("checkIn", Dates.formatCsv(r.checkIn));
   156	        map.put("checkOut", Dates.formatCsv(r.checkOut));
   157	        map.put("guests", r.guests);
   158	        map.put("ratePlan", r.ratePlan.name());
   159	        map.put("nights", r.nights);
   160	        map.put("subtotal", r.subtotal);
   161	        map.put("discount", r.discount);
   162	        map.put("total", r.total);
   163	        map.put("status", r.status.name());
   164	        map.put("amountPaid", r.amountPaid);
   165	        map.put("refund", r.refund);
   166	        return map;
   167	    }
   168	
   169	    private static Map<String, Object> receiptToDto(Reservation r, String receipt) {
   170	        Map<String, Object> map = new java.util.LinkedHashMap<>();
   171	        map.put("title", "Comprovante de reserva");
   172	        map.put("reservationId", r.id);
   173	        map.put("guestName", r.guestName);
   174	        map.put("guestCpf", r.guestCpf);
   175	        map.put("roomNumber", r.roomNumber);
   176	        map.put("roomType", "");
   177	        map.put("checkIn", Dates.formatCsv(r.checkIn));
   178	        map.put("checkOut", Dates.formatCsv(r.checkOut));
   179	        map.put("nights", r.nights);
   180	        map.put("subtotal", r.subtotal);
   181	        map.put("discount", r.discount);
   182	        map.put("total", r.total);
   183	        return map;
   184	    }
   185	
   186	    private static void sendError(Context ctx, String code, String message, int status) {
   187	        ctx.status(status).json(Map.of("error", code, "message", message));
   188	    }
   189	}
