   100	                                .append(Dates.formatCsv(r.checkOut)).append(",")
   101	                                .append(r.status.name()).append(",")
   102	                                .append(String.format("%.2f", amount)).append("\n");
   103	
   104	                        total = total.add(amount);
   105	                    }
   106	                }
   107	            }
   108	
   109	            csv.append("total,,,,").append(String.format("%.2f", total)).append("\n");
   110	
   111	            ctx.contentType("text/csv; charset=utf-8").result(csv.toString());
   112	        } catch (Exception e) {
   113	            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
   114	        }
   115	    }
   116	}
