     1	package com.pousada.service;
     2	
     3	import com.pousada.database.ReservationDao;
     4	import com.pousada.database.RoomDao;
     5	import com.pousada.database.MessageDao;
     6	import com.pousada.model.Reservation;
     7	import com.pousada.model.ReservationStatus;
     8	import com.pousada.model.RatePlanType;
     9	import com.pousada.model.Room;
    10	import com.pousada.rateplan.RatePlan;
    11	import com.pousada.rateplan.RatePlanException;
    12	import com.pousada.rateplan.RatePlanFactory;
    13	import com.pousada.util.Dates;
    14	
    15	import java.math.BigDecimal;
    16	import java.time.LocalDate;
    17	import java.util.HashMap;
    18	import java.util.List;
    19	import java.util.Map;
    20	
    21	public class ReservationService {
    22	    public static Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    23	                                                LocalDate checkIn, LocalDate checkOut, int guests,
    24	                                                RatePlanType ratePlan, String companyCode) throws Exception {
    25	        // Validate room exists
    26	        Room room = RoomDao.findByNumber(roomNumber);
    27	        if (room == null) {
    28	            throw new ApiException("ROOM_NOT_FOUND", "Room not found", 404);
    29	        }
    30	
    31	        // Validate dates
    32	        if (checkIn.isAfter(checkOut)) {
    33	            throw new ApiException("INVALID_REQUEST", "Check-out must be after check-in", 400);
    34	        }
    35	
    36	        int nights = Dates.countNights(checkIn, checkOut);
    37	        if (nights < 1) {
    38	            throw new ApiException("INVALID_REQUEST", "Invalid date range", 400);
    39	        }
    40	
    41	        // Validate guests
    42	        if (guests < 1) {
    43	            throw new ApiException("INVALID_REQUEST", "At least 1 guest is required", 400);
    44	        }
    45	        if (guests > room.capacity) {
    46	            throw new ApiException("CAPACITY_EXCEEDED", "Too many guests for this room", 422);
    47	        }
    48	
    49	        // Validate and calculate price using rate plan
    50	        RatePlan plan = RatePlanFactory.create(ratePlan);
    51	        Map<String, Object> context = new HashMap<>();
    52	        context.put("companyCode", companyCode);
    53	        context.put("roomType", room.type);
    54	
    55	        try {
    56	            plan.validate(room.capacity, nights, checkIn, checkOut, guests, context);
    57	        } catch (RatePlanException e) {
    58	            throw new ApiException("INVALID_REQUEST", e.getMessage(), 400);
    59	        }
    60	
    61	        // Check room availability
    62	        for (LocalDate date = checkIn; date.isBefore(checkOut); date = date.plusDays(1)) {
    63	            List<Reservation> existing = ReservationDao.findByRoomAndNight(roomNumber, date);
    64	            if (!existing.isEmpty()) {
    65	                throw new ApiException("ROOM_UNAVAILABLE", "Room is not available for the selected dates", 409);
    66	            }
    67	        }
    68	
    69	        // Calculate price
    70	        RatePlan.PriceCalculation pricing = plan.calculate(room.nightlyRate, nights, checkIn, checkOut, context);
    71	
    72	        // Create reservation
    73	        Reservation reservation = ReservationDao.insert(
    74	                roomNumber, guestName, guestEmail, guestCpf,
    75	                checkIn, checkOut, guests, ratePlan, companyCode,
    76	                nights, pricing.subtotal, pricing.discount, pricing.total
    77	        );
    78	
    79	        return reservation;
    80	    }
    81	
    82	    public static Reservation getReservation(int id) throws Exception {
    83	        Reservation reservation = ReservationDao.findById(id);
    84	        if (reservation == null) {
    85	            throw new ApiException("RESERVATION_NOT_FOUND", "Reservation not found", 404);
    86	        }
    87	        return reservation;
    88	    }
    89	
    90	    public static Reservation confirmReservation(int id, BigDecimal amountPaid) throws Exception {
    91	        Reservation reservation = getReservation(id);
    92	
    93	        if (reservation.status != ReservationStatus.PENDING) {
    94	            throw new ApiException("OPERATION_NOT_ALLOWED", "Can only confirm a pending reservation", 409);
    95	        }
    96	
    97	        ReservationDao.updateStatus(id, ReservationStatus.CONFIRMED);
    98	        ReservationDao.updateAmountPaid(id, amountPaid);
    99	
   100	        // Send confirmation email
   101	        String receiptText = generateReceipt(reservation);
   102	        String emailBody = """
   103	                Olá, %s!
   104	
   105	                Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
   106	
   107	                %s
   108	
   109	                A entrada é a partir das 14h, e a saída, até as 12h.
   110	                Até breve!""".formatted(reservation.guestName, receiptText);
   111	
   112	        MessageDao.insert("EMAIL", reservation.guestEmail,
   113	                "Reserva confirmada - Pousada Maré Alta", emailBody);
   114	
   115	        return getReservation(id);
   116	    }
   117	
   118	    public static Reservation cancelReservation(int id) throws Exception {
   119	        Reservation reservation = getReservation(id);
   120	
   121	        if (reservation.status == ReservationStatus.CHECKED_OUT || reservation.status == ReservationStatus.CANCELLED) {
   122	            throw new ApiException("OPERATION_NOT_ALLOWED", "Can only cancel before check-out", 409);
   123	        }
   124	
   125	        RatePlan plan = RatePlanFactory.create(reservation.ratePlan);
   126	        BigDecimal refund = plan.calculateRefund(reservation.amountPaid);
   127	
   128	        ReservationDao.updateStatus(id, ReservationStatus.CANCELLED);
   129	        ReservationDao.updateRefund(id, refund);
   130	
   131	        return getReservation(id);
   132	    }
   133	
   134	    public static Reservation checkInReservation(int id) throws Exception {
   135	        Reservation reservation = getReservation(id);
   136	
   137	        if (reservation.status != ReservationStatus.CONFIRMED) {
   138	            throw new ApiException("OPERATION_NOT_ALLOWED", "Can only check in a confirmed reservation", 409);
   139	        }
   140	
   141	        ReservationDao.updateStatus(id, ReservationStatus.CHECKED_IN);
   142	        return getReservation(id);
   143	    }
   144	
   145	    public static Reservation checkOutReservation(int id) throws Exception {
   146	        Reservation reservation = getReservation(id);
   147	
   148	        if (reservation.status != ReservationStatus.CHECKED_IN) {
   149	            throw new ApiException("OPERATION_NOT_ALLOWED", "Can only check out a checked-in reservation", 409);
   150	        }
   151	
   152	        ReservationDao.updateStatus(id, ReservationStatus.CHECKED_OUT);
   153	        return getReservation(id);
   154	    }
   155	
   156	    public static String generateReceipt(Reservation reservation) throws Exception {
   157	        Room room = RoomDao.findByNumber(reservation.roomNumber);
   158	        String nights = reservation.nights == 1 ? "1 diária" : reservation.nights + " diárias";
   159	        String discount = reservation.discount.compareTo(BigDecimal.ZERO) > 0 ?
   160	                "\nDesconto: R$ " + formatMoney(reservation.discount) : "";
   161	
   162	        return String.format(
   163	                "Comprovante de reserva nº %d%n" +
   164	                        "Hóspede: %s (CPF %s)%n" +
   165	                        "Quarto: %d (%s)%n" +
   166	                        "Entrada: %s | Saída: %s | %s%n" +
   167	                        "Diárias: R$ %s%s%n" +
   168	                        "Total: R$ %s",
   169	                reservation.id,
   170	                reservation.guestName,
   171	                reservation.guestCpf,
   172	                reservation.roomNumber,
   173	                room.type,
   174	                Dates.formatBr(reservation.checkIn),
   175	                Dates.formatBr(reservation.checkOut),
   176	                nights,
   177	                formatMoney(reservation.subtotal),
   178	                discount,
   179	                formatMoney(reservation.total)
   180	        );
   181	    }
   182	
   183	    private static String formatMoney(BigDecimal value) {
   184	        return String.format("%.2f", value).replace(".", ",");
   185	    }
   186	}
