     6	import java.math.BigDecimal;
     7	import java.time.LocalDate;
     8	import java.util.Map;
     9	
    10	public class CorporateRatePlan implements RatePlan {
    11	    private static final Map<String, BigDecimal> DISCOUNTS = Map.of(
    12	            "TECNOSUL", new BigDecimal("0.12"),
    13	            "AGROVALE", new BigDecimal("0.18"),
    14	            "FARMAVIDA", new BigDecimal("0.25")
    15	    );
    16	
    17	    @Override
    18	    public void validate(int roomCapacity, int nights, LocalDate checkIn, LocalDate checkOut,
    19	                         int guests, Map<String, Object> context) throws RatePlanException {
    20	        String companyCode = (String) context.get("companyCode");
    21	        if (companyCode == null || !DISCOUNTS.containsKey(companyCode)) {
    22	            throw new RatePlanException("Invalid or missing company code for CORPORATE plan");
    23	        }
    24	    }
    25	
    26	    @Override
    27	    public PriceCalculation calculate(BigDecimal nightlyRate, int nights, LocalDate checkIn, LocalDate checkOut,
    28	                                      Map<String, Object> context) {
    29	        String companyCode = (String) context.get("companyCode");
    30	        BigDecimal subtotal = BigDecimal.ZERO;
    31	
    32	        for (int i = 0; i < nights; i++) {
    33	            LocalDate date = checkIn.plusDays(i);
    34	            BigDecimal rate = nightlyRate;
    35	            if (Dates.isHighSeason(date)) {
    36	                rate = rate.multiply(BigDecimal.valueOf(1.20));
    37	            }
    38	            rate = Money.round(rate);
    39	            subtotal = subtotal.add(rate);
    40	        }
    41	        subtotal = Money.round(subtotal);
    42	
    43	        BigDecimal discountPercentage = DISCOUNTS.get(companyCode);
    44	        BigDecimal discount = subtotal.multiply(discountPercentage);
    45	        discount = Money.round(discount);
    46	
    47	        BigDecimal total = subtotal.subtract(discount);
    48	        total = Money.round(total);
    49	
    50	        return new PriceCalculation(subtotal, discount, total);
    51	    }
    52	
    53	    @Override
    54	    public BigDecimal calculateRefund(BigDecimal amountPaid) {
    55	        return amountPaid;
    56	    }
    57	}
